/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-reveal .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-reveal .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; }
.sl-hero-reveal .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; filter: brightness(0.9); }
.sl-hero-reveal .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-reveal .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-reveal {
    min-height: 85vh;
}
.sl-hero-reveal .sl-reveal-title {
    letter-spacing: -0.03em;
}
.sl-hero-reveal .sl-hover-lift {
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.sl-hero-reveal .sl-hover-lift:hover {
    transform: translateY(-3px);
    box-shadow: 0 15px 30px rgba(13, 110, 253, 0.2) !important;
}

/* 3D Mockup Styling */
.sl-hero-reveal .sl-dashboard-mockup {
    transform: perspective(1000px) rotateY(-15deg) rotateX(5deg) scale(0.9);
    transform-origin: center right;
    box-shadow: -20px 20px 60px rgba(0,0,0,0.1) !important;
    animation: slMockupEntrance 1.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    opacity: 0;
}
.sl-hero-reveal .sl-mock-widget {
    opacity: 0;
    transform: translateY(15px);
    animation: slWidgetFade 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    animation-delay: 0.8s; /* Start after mockup entrance */
}

@keyframes slMockupEntrance {
    0% { opacity: 0; transform: perspective(1000px) rotateY(-25deg) rotateX(10deg) scale(0.8) translateZ(-100px); }
    100% { opacity: 1; transform: perspective(1000px) rotateY(-15deg) rotateX(5deg) scale(0.9) translateZ(0); }
}
@keyframes slWidgetFade {
    to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 991px) {
    .sl-hero-reveal .sl-dashboard-mockup {
        transform: none !important;
        animation: none !important;
        opacity: 1;
        margin-top: 2rem;
    }
    .sl-hero-reveal .sl-mock-widget {
        opacity: 1;
        transform: none;
        animation: none;
    }
}

